  msg.deye = { cfg, target: ip + ':' + port, reads: reads.map((r) => ({ start: r.start, count: r.count })), i: 0, blocks: [] };
  node.status({ fill: 'blue', shape: 'dot', text: 'Deye ' + sel.family + ' -> Solarman-V5' });
  return [msg, null, null];
}
if (sel.communication === 'modbus_tcp') {
  const read = MODBUS_PROFILES[sel.family];
  if (!read) return idle('unbekanntes Modbus-Profil: ' + sel.family);
  const port = num(conn.port, 502);
  msg.mb = { conn: { ip, port, unit_id: num(conn.unit_id, 1) }, profile: sel.family, read: { fc: read.fc, addr: read.addr, count: read.count }, target: ip + ':' + port };
  node.status({ fill: 'blue', shape: 'dot', text: 'Modbus ' + sel.family + ' @ ' + ip + ':' + port });
  return [null, msg, null];
}
return idle('unbekannte Kommunikationsmethode');

// Solarman-V5-Transport: Modbus-RTU im Solarman-V5-Rahmen ueber TCP 8899 - die
// ROBUSTE Deye-Anbindung (ersetzt die flaky AT-CLI ueber UDP 48899). Eine
// einzige, geordnete TCP-Verbindung pro Poll (der Logger erlaubt nur EINEN
// Client), sequenzielle Bloecke, Reconnect je Poll.
//
// Traegt eine KOPIE von edge-app/nodered/deye/solarman-v5.js (ein Node-RED-Flow
// ist self-contained JSON und kann keine Repo-Datei zur Laufzeit requiren).
// Quelle der Wahrheit + Offline-Tests: deye/solarman-v5.js - beide synchron halten.
const net = global.get('net');
if (!net) {
  node.status({ fill: 'red', shape: 'ring', text: 'net fehlt (settings.js)' });
  node.error('functionGlobalContext.net in settings.js setzen (siehe DEYE.md)', msg);
