  if (mb.readUInt16LE(mb.length - 2) !== modbusCrc16(mb.slice(0, mb.length - 2))) throw new Error('Modbus-CRC');
  if (mb[1] & 0x80) throw new Error('Modbus-Ausnahme 0x' + mb[2].toString(16));
  if (mb[1] !== 0x03) throw new Error('Modbus-Funktion 0x' + mb[1].toString(16));
