// Decodiert die gelesenen Register in die flache edge/telemetry-Nachricht.
// Nur die kanonischen Cloud-Felder gehen an vp-telemetrie; die Batterieleistung
// (batt_kw) ist reine Kalibrierhilfe (Status/Debug) - die Cloud leitet sie aus
// der Leistungsbilanz ab. Quelle der Wahrheit + Tests:
// edge-app/nodered/deye/deye-decode.js
const ctx = msg.deye;
